@parity "dart2wasm/lib/intrinsics.dart:607 Intrinsifier.generateInstanceGetterIntrinsic" generate_instance_getter_intrinsic(self::Intrinsifier, node::NirCall)::Union{WasmBuilder.IR.ValueType,Nothing} = nothing

"""
